    'RegistrationText'=>'Registrovaným instancím SimpleRisk je okamžitě udělen přístup k doplňkům Upgrade and Secure Controls Framework (SCF). Upgrade Extra poskytuje možnost zálohovat a upgradovat vaši instanci SimpleRisk kliknutím na tlačítko. Secure Controls Framework (SCF) Extra poskytuje společný rámec řízení, který je integrován do funkce SimpleRisk Governance. Po registraci SimpleRisk budou vaše registrační informace odeslány na server hostovaný SimpleRisk. Poskytnuté registrační informace použije SimpleRisk k upozornění zákazníků na nová vydání a aktualizace zabezpečení. Registrace SimpleRisk vás přihlásí k odběru našich marketingových sdělení, ale můžete se kdykoli odhlásit pomocí odkazu pro odhlášení v těchto sděleních. SimpleRisk respektuje soukromí našich zákazníků a informace poskytnuté nám prostřednictvím procesu registrace SimpleRisk nebudou nikdy prodány třetí straně.',
